  const form = document.getElementById('contact-form');
  const successBanner = document.getElementById('success-banner');

  const fields = {
    fullName: {
      input: document.getElementById('full-name'),
      error: document.getElementById('full-name-error'),
      validate(value) {
        if (!value.trim()) return 'Full name is required.';
        if (value.trim().length < 2) return 'Please enter your full name.';
        return null;
      },
    },
    email: {
      input: document.getElementById('email'),
      error: document.getElementById('email-error'),
      validate(value) {
        if (!value.trim()) return 'Email address is required.';
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
          return 'Please enter a valid email address.';
        return null;
      },
    },
    phone: {
      input: document.getElementById('phone'),
      error: document.getElementById('phone-error'),
      validate(value) {
        if (!value.trim()) return null; // optional
        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
          return 'Please enter a valid phone number (e.g. +1 555-123-4567).';
        return null;
      },
    },
  };

  function setFieldState(field, errorMsg) {
    const { input, error } = field;
    if (errorMsg) {
      input.classList.add('is-invalid');
      input.classList.remove('is-valid');
      error.textContent = errorMsg;
      error.classList.add('visible');
      input.setAttribute('aria-invalid', 'true');
    } else {
      input.classList.remove('is-invalid');
      if (input.value.trim()) input.classList.add('is-valid');
      else input.classList.remove('is-valid');
      error.textContent = '';
      error.classList.remove('visible');
      input.setAttribute('aria-invalid', 'false');
    }
  }

  // Live validation on blur
  Object.values(fields).forEach((field) => {
    field.input.addEventListener('blur', () => {
      const err = field.validate(field.input.value);
      setFieldState(field, err);
    });

    // Clear error on input once field has been touched
    field.input.addEventListener('input', () => {
      if (field.input.classList.contains('is-invalid')) {
        const err = field.validate(field.input.value);
        setFieldState(field, err);
      }
    });
  });

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    successBanner.classList.remove('visible');

    let isValid = true;
    Object.values(fields).forEach((field) => {
      const err = field.validate(field.input.value);
      setFieldState(field, err);
      if (err) isValid = false;
    });

    if (!isValid) {
      const firstInvalid = Object.values(fields).find((f) =>
        f.input.classList.contains('is-invalid')
      );
      if (firstInvalid) firstInvalid.input.focus();
      return;
    }

    // Simulate submission
    successBanner.classList.add('visible');
    form.reset();
    Object.values(fields).forEach((f) => {
      f.input.classList.remove('is-valid', 'is-invalid');
    });
  });
})();
